begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values
 ('d3510000-0000-4000-8000-000000000001','catalogue-owner@example.test',now()),
 ('d3510000-0000-4000-8000-000000000002','catalogue-staff@example.test',now()),
 ('d3510000-0000-4000-8000-000000000003','catalogue-outsider@example.test',now());
set local role authenticated;
set local "request.jwt.claims"='{"sub":"d3510000-0000-4000-8000-000000000001","role":"authenticated"}';
select set_config('test.tenant',create_tenant('Synthetic catalogue','catalogue-editing',gen_random_uuid())::text,true);
select set_config('test.cat',create_item_category(current_setting('test.tenant')::uuid,gen_random_uuid(),'Books','{"en":"Books","sv":"Old books"}')::text,true);
select publish_store_policy(current_setting('test.tenant')::uuid,gen_random_uuid(),null,(current_store_policy(current_setting('test.tenant')::uuid)->'policy')||'{"vatModeStoreOwned":"store_full"}');
select set_config('test.purchase',register_purchase(current_setting('test.tenant')::uuid,gen_random_uuid(),'Synthetic book',10000,'Synthetic receipt',false)::text,true);
select set_config('test.item',accept_item(current_setting('test.tenant')::uuid,gen_random_uuid(),'purchase',current_setting('test.purchase')::uuid,null,20000)::text,true);
select correct_item_attribute(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.item')::uuid,'category',' old BOOKS ','Synthetic classification');
select is((select category_id from item_category_links where item_id=current_setting('test.item')::uuid order by seq desc limit 1),current_setting('test.cat')::uuid,'unique translated text links automatically');
select set_config('test.edit',gen_random_uuid()::text,true);
select lives_ok($$select update_item_category(current_setting('test.tenant')::uuid,current_setting('test.edit')::uuid,current_setting('test.cat')::uuid,0,'Reading','{"en":"Reading","sv":"New books"}',true)$$,'owner renames category');
select is((select value->>'name' from jsonb_array_elements(item_category_catalogue(current_setting('test.tenant')::uuid)) where value->>'id'=current_setting('test.cat')),'Reading','catalogue reads latest version');
reset role;
select is(komisio_private.item_title(current_setting('test.tenant')::uuid,current_setting('test.item')::uuid)->>'category','New books','linked current display follows translated rename');
set local role authenticated;
select is((select value from item_attribute_corrections where item_id=current_setting('test.item')::uuid and slug='category' order by seq desc limit 1),'old BOOKS','original observation stays intact');
select lives_ok($$select update_item_category(current_setting('test.tenant')::uuid,current_setting('test.edit')::uuid,current_setting('test.cat')::uuid,0,'Reading','{"en":"Reading","sv":"New books"}',true)$$,'exact retry adds no version');
select is((select count(*) from item_category_versions where category_id=current_setting('test.cat')::uuid),1::bigint,'one immutable version');
select throws_ok($$select update_item_category(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.cat')::uuid,0,'Stale','{"en":"Stale"}',true)$$,'P0001','CATALOGUE_CHANGED','stale editor rejected');
select throws_ok($$select update_item_category(current_setting('test.tenant')::uuid,current_setting('test.edit')::uuid,current_setting('test.cat')::uuid,0,'Changed','{"en":"Changed"}',true)$$,'P0001','REQUEST_CONFLICT','changed replay rejected');
select is(delete_catalogue_record(current_setting('test.tenant')::uuid,'category',current_setting('test.cat'))->>'ok','false','linked category cannot be deleted');
select lives_ok($$select update_item_category(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.cat')::uuid,1,'Reading','{"en":"Reading","sv":"New books"}',false)$$,'used category can be deactivated');
reset role;
select is(komisio_private.item_title(current_setting('test.tenant')::uuid,current_setting('test.item')::uuid)->>'category','New books','deactivation retains existing display');
set local role authenticated;
select set_config('test.type',create_item_type(current_setting('test.tenant')::uuid,gen_random_uuid(),'Synthetic type','en','[{"slug":"description","expected":true,"sort":0}]'),true);
select set_config('test.profile',(select value::text from jsonb_array_elements(attribute_vocabulary(current_setting('test.tenant')::uuid)->'types') where value->>'slug'=current_setting('test.type')),true);
select lives_ok($$select update_item_type(current_setting('test.tenant')::uuid,current_setting('test.type'),current_setting('test.profile')::jsonb,'{"labels":{"en":"Renamed type"},"suggestedCategory":"Reading","active":false,"attributes":[{"slug":"description","expected":true,"sort":0}]}')$$,'type labels, profile and availability can be edited');
select throws_ok($$select update_item_type(current_setting('test.tenant')::uuid,current_setting('test.type'),current_setting('test.profile')::jsonb,'{"labels":{"en":"Stale"},"active":true}')$$,'P0001','CATALOGUE_CHANGED','type edits reject stale snapshot');
select throws_ok($$update item_category_versions set name='Direct'$$,'42501',null,'direct version writes denied');
select throws_ok($$delete from item_category_links$$,'42501',null,'direct link deletes denied');
select create_invitation(current_setting('test.tenant')::uuid,'catalogue-staff@example.test','staff',repeat('d',64));
set local "request.jwt.claims"='{"sub":"d3510000-0000-4000-8000-000000000002","role":"authenticated"}';
select accept_invitation(repeat('d',64));
select throws_ok($$select update_item_category(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.cat')::uuid,2,'Denied','{"en":"Denied"}',true)$$,'42501','FORBIDDEN','staff cannot edit settings');
select throws_ok($$select update_item_type(current_setting('test.tenant')::uuid,current_setting('test.type'),'{}','{}')$$,'42501','FORBIDDEN','staff cannot edit types');
set local "request.jwt.claims"='{"sub":"d3510000-0000-4000-8000-000000000003","role":"authenticated"}';
select throws_ok($$select item_category_catalogue(current_setting('test.tenant')::uuid)$$,'42501','FORBIDDEN','outsider cannot read catalogue');
select is((select count(*) from item_category_links),0::bigint,'cross-store links hidden');
set local "request.jwt.claims"='{"sub":"d3510000-0000-4000-8000-000000000001","role":"authenticated"}';
select throws_ok($$select create_item_category(current_setting('test.tenant')::uuid,gen_random_uuid(),'Reading','{"en":"Reading"}')$$,'P0001','CATEGORY_EXISTS','create checks renamed current names');
select set_config('test.other',create_item_category(current_setting('test.tenant')::uuid,gen_random_uuid(),'Other','{"en":"Other","sv":"Shared"}')::text,true);
select set_config('test.ambiguous',create_item_category(current_setting('test.tenant')::uuid,gen_random_uuid(),'Alternative','{"en":"Alternative","sv":"Shared"}')::text,true);
select correct_item_attribute(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.item')::uuid,'category','Shared','Synthetic ambiguous choice');
select ok((select category_id is null from item_category_links where item_id=current_setting('test.item')::uuid order by seq desc limit 1),'ambiguous names stay unlinked');
select set_config('test.row',gen_random_uuid()::text,true);
select lives_ok($$select edit_inventory_row_with_category(current_setting('test.tenant')::uuid,current_setting('test.row')::uuid,current_setting('test.item')::uuid,'{"title":"Synthetic book","category":"Shared","version":0}','Synthetic book','Shared',null,null,current_setting('test.other')::uuid)$$,'explicit ID resolves ambiguous category');
select is((select category_id from item_category_links where item_id=current_setting('test.item')::uuid order by seq desc limit 1),current_setting('test.other')::uuid,'chosen ID is retained');
select lives_ok($$select edit_inventory_row_with_category(current_setting('test.tenant')::uuid,current_setting('test.row')::uuid,current_setting('test.item')::uuid,'{"title":"Synthetic book","category":"Shared","version":0}','Synthetic book','Shared',null,null,current_setting('test.other')::uuid)$$,'explicit selection safely retries');
select throws_ok($$select edit_inventory_row_with_category(current_setting('test.tenant')::uuid,current_setting('test.row')::uuid,current_setting('test.item')::uuid,'{"title":"Synthetic book","category":"Shared","version":0}','Synthetic book','Shared',null,null,current_setting('test.ambiguous')::uuid)$$,'P0001','REQUEST_CONFLICT','same text with another category ID is a conflicting replay');
select update_item_category(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.other')::uuid,0,'Selected','{"en":"Selected","sv":"Chosen"}',false);
select lives_ok($$select edit_inventory_row_with_category(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.item')::uuid,'{"title":"Synthetic book","category":"Chosen","version":1}','Renamed book','Chosen',null,null,null)$$,'ordinary title edit retains inactive category');
select is((select category_id from item_category_links where item_id=current_setting('test.item')::uuid order by seq desc limit 1),current_setting('test.other')::uuid,'inactive link survives unrelated edit');
select throws_ok($$select edit_inventory_row_with_category(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.item')::uuid,'{"title":"Renamed book","category":"Chosen","version":2}','Renamed book','New books',null,null,current_setting('test.cat')::uuid)$$,'P0001','CATEGORY_NOT_FOUND','inactive category cannot be newly selected');
select lives_ok($$select edit_inventory_row_with_category(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.item')::uuid,'{"title":"Renamed book","category":"Chosen","version":2}','Renamed book','',null,null,null)$$,'category can be cleared');
select ok((select category_id is null from item_category_links where item_id=current_setting('test.item')::uuid order by seq desc limit 1),'clearing removes current association');
select is(delete_catalogue_record(current_setting('test.tenant')::uuid,'category',current_setting('test.other'))->>'ok','false','historically used category remains protected after clearing');
select set_config('test.ambiguous',create_item_category(current_setting('test.tenant')::uuid,gen_random_uuid(),'Unused source','{"en":"Unused source"}')::text,true);
select update_item_category(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.ambiguous')::uuid,0,'Unused edited','{"en":"Unused edited"}',false);
select is(delete_catalogue_record(current_setting('test.tenant')::uuid,'category',current_setting('test.ambiguous'))->>'ok','true','unused edited category can be deleted');
select set_config('test.profile',(select value::text from jsonb_array_elements(attribute_vocabulary(current_setting('test.tenant')::uuid)->'types') where value->>'slug'=current_setting('test.type')),true);
select update_item_type(current_setting('test.tenant')::uuid,current_setting('test.type'),current_setting('test.profile')::jsonb,'{"labels":{"en":"Renamed type"},"suggestedCategory":"","active":true,"attributes":[{"slug":"description","expected":true,"sort":0}]}');
select classify_items(current_setting('test.tenant')::uuid,gen_random_uuid(),jsonb_build_array(jsonb_build_object('id',current_setting('test.item'),'version',3)),current_setting('test.type'),null);
select set_config('test.profile',(select value::text from jsonb_array_elements(attribute_vocabulary(current_setting('test.tenant')::uuid)->'types') where value->>'slug'=current_setting('test.type')),true);
select update_item_type(current_setting('test.tenant')::uuid,current_setting('test.type'),current_setting('test.profile')::jsonb,'{"labels":{"en":"Current renamed type"},"suggestedCategory":"","active":false,"attributes":[{"slug":"description","expected":true,"sort":0}]}');
select is(delete_catalogue_record(current_setting('test.tenant')::uuid,'type',current_setting('test.type'))->>'ok','false','used type cannot be hard deleted');
select lives_ok($$select edit_inventory_row_with_category(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.item')::uuid,'{"title":"Renamed book","category":"","version":4}','Final title','',current_setting('test.type'),null,null)$$,'existing inactive type does not block unrelated edit');
select classify_items(current_setting('test.tenant')::uuid,gen_random_uuid(),jsonb_build_array(jsonb_build_object('id',current_setting('test.item'),'version',5)),null,null);
select throws_ok($$select classify_items(current_setting('test.tenant')::uuid,gen_random_uuid(),jsonb_build_array(jsonb_build_object('id',current_setting('test.item'),'version',6)),current_setting('test.type'),null)$$,'P0001','ITEM_TYPE_UNDEFINED','inactive type cannot be newly assigned');
reset role;
select throws_ok($$update item_category_versions set name='Mutated' where category_id=current_setting('test.cat')::uuid$$,'P0001',null,'versions reject in-place mutation even with table privileges');
select * from finish();
rollback;
